public int findLargestSubstring(List<String> strings) {
        int maxLength = 0;
        for (String s : strings) {
            for (int i = 0; i < s.length(); i++) {
                String subStr = s.substring(i);
                if (strings.contains(subStr) || strings.contains(subStr.reverse())) {
                    maxLength = Math.max(maxLength, subStr.length());
                }
            }
        }
        return maxLength;
    }

public int findLargestSubstring(List<String> strings) {
    for (int i = count(strings); i > 0; i--) {
        for (int len = 0; len <= i; len++) {
            String prefix = strings.get(0);
            for (int j = len; j < strings.size(); j++) {
                String suffix = strings.get(j);
                if (suffix.startsWith(prefix) || suffix.endsWith(prefix)) {
                    return len;
                }
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) return 0;

    return findLargestSubstring(strings, 0, strings.size() - 1);
}

private int findLargestSubstring(List<String> strings, int start, int end) {
    if (start == end) return 1;

    int max = 0;
    for (int i = start; i <= end; i++) {
        for (int j = i; j <= end; j++) {
            String sub = strings.get(i) + strings.get(j);
            if (isSubstring(sub, strings)) {
                max = Math.max(max, j - i + 1);
            }
            sub = strings.get(j) + strings.get(i);
            if (isSubstring(sub, strings)) {
                max = Math.max(max, j - i + 1);
            }
        }
    }

    return max;
}

private boolean isSubstring(String sub, List<String> strings) {
    for (String str : strings) {
        if (str.contains(sub)) {
            return true;
        }
    }
    return false;
}

