public static int countOilDeposits(char[][] grid) {
    Set<Character> seen = new HashSet<>();
    int count = 0;

    for (char[] row : grid) {
        for (char e : row) {
            if (e == '@') {
                count++;
                markVisited(e, seen, row, grid.length);
            }
        }
    }

    return count;
}

private static void markVisited(char e, Set<Character> seen, char[] row, int length) {
    seen.add(e);

    int j;
    for (j = 0; j < length; j++) {
        if (row[j] == '*' && !seen.contains(row[j])) {
            markVisited(row[j], seen, row, length);
        }
    }
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int[][] directions = new int[][]{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                HashSet<Integer> visited = new HashSet<>();
                dfs(grid, visited, i, j, directions);
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, HashSet<Integer> visited, int i, int j, int[][] directions) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] == '*' || visited.contains(i * cols + j)) {
        return;
    }
    visited.add(i * cols + j);
    for (int[] dir : directions) {
        dfs(grid, visited, i + dir[0], j + dir[1], directions);
    }
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    boolean[][] visited = new boolean[grid.length][grid[0].length];
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                dfs(grid, visited, i, j);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || visited[i][j] || grid[i][j] != '@') {
        return;
    }
    visited[i][j] = true;
    dfs(grid, visited, i - 1, j);
    dfs(grid, visited, i + 1, j);
    dfs(grid, visited, i, j - 1);
    dfs(grid, visited, i, j + 1);
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                if (isOilDeposit(grid, i, j)) {
                    count++;
                }
            }
        }
    }
    return count;
}

private static boolean isOilDeposit(char[][] grid, int x, int y) {
    if (x < 0 || y < 0 || x >= grid.length || y >= grid[x].length) {
        return false;
    }
    if (grid[x][y] != '@') {
        return false;
    }
    // Mark as visited to avoid revisiting
    grid[x][y] = '.';
    // Explore adjacent squares
    boolean up = isOilDeposit(grid, x-1, y);
    boolean down = isOilDeposit(grid, x+1, y);
    boolean left = isOilDeposit(grid, x, y-1);
    boolean right = isOilDeposit(grid, x, y+1);
    return up && down && left && right;
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    int rows = grid.length;
    int cols = grid[0].length;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
            // Depth-First Search (DFS) to explore all oil pockets
                markPockets(grid, i, j);
            }
        }
    }
    return count;
}

private static void markPockets(char[][] grid, int x, int y) {
    // Check for boundary and if already marked
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] != '@') {
        return;
    }
    grid[x][y] = '*'; // Mark the visited oil pocket

    // Mark adjacent cells
    markPockets(grid, x + 1, y);
    markPockets(grid, x - 1, y);
    markPockets(grid, x, y + 1);
    markPockets(grid, x, y - 1);
}

