public boolean canArrange(int[] arr, int k) {
    int[] count = new int[k];
    for (int num : arr) {
        count[num % k]++;
    }

    int oddCount = 0, evenCount = 0;
    for (int i = 1; i < k; i++) {
        if (count[i] != count[k - i]) {
            return false;
        }
        oddCount += count[i];
        evenCount += count[k - i];
    }

    if (k % 2 != 0) {
        return oddCount % 2 == 0;
    }

    return evenCount % 2 == 0;
}

