        if (remainder == 0) {
            if (map.containsKey(0)) {
                map.put(0, map.get(0) - 1);
                if (map.get(0) == 0) {
                    map.remove(0);
                }
            }
        } else {
            if (map.containsKey(k - remainder)) {
                map.put(k - remainder, map.get(k - remainder) - 1);
                if (map.get(k - remainder) == 0) {
                    map.remove(k - remainder);
                }
            }
        }
    }

    return map.isEmpty();
}

