public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        if (!graph.containsKey(u)) graph.put(u, new ArrayList<>());
        if (!graph.containsKey(v)) graph.put(v, new ArrayList<>());
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    int[] visited = new int[n];
    int time = 0;
    time += dfs(0, graph, hasApple, visited);

    return time - 1; // Removing the extra 1 representing the return trip
}

private int dfs(int node, Map<Integer, List<Integer>> graph, boolean[] hasApple, int[] visited) {
    if (visited[node] == 1) return 0; // Already visited, return 0
    visited[node] = 1; // Mark visited
    int totalTime = 0;

    for (int neighbor : graph.get(node)) {
        totalTime += dfs(neighbor, graph, hasApple, visited); // Include the time taken to reach the neighbor
    }

    if (hasApple[node] || totalTime > 0) { // If the node has an apple or any neighbors have an apple, add 2 time units for return trip
        totalTime += 2;
    }

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Convert edges to an adjacency list
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    // Topological sort to remove nodes witch are on the path to the root and have no apples below them
    List<Integer> topologicalOrder = new ArrayList<>();
    Queue<Integer> q = new LinkedList<>();
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) q.offer(i);
    }
    while (!q.isEmpty()) {
        int u = q.poll();
        topologicalOrder.add(u);
        for (int v : graph.get(u)) {
            if (hasApple[v]) {
                q.offer(v);
            }
        }
    }

    // Calculate the minimum time passing through each node excluding the first node (where it starts)
    int ans = 0;
    for (int i = 0; i < topologicalOrder.size() - 1; i++) {
        int u = topologicalOrder.get(i);
        int v = topologicalOrder.get(i + 1);
        ans += Time(u, v);
    }

    return ans + (hasApple[0] ? 1 : 0); // Added one extra unit for the round trip
}

private int Time(int u, int v) {
    int[] jump = new int[2];
    jump[0] = u == v ? 0 : jump[u] == 0 ? Integer.MAX_VALUE / 2 : jump[u] + 1;
    jump[1] = u == v ? 0 : jump[u] == 0 ? Integer.MAX_VALUE / 2 : jump[u] + 1;
    for (int i : graph.get(u)) {
        if (i != v) {
            jump[0] = Math.min(jump[0], jump[1] + Time(i, v));
        }
    }
    for (int i : graph.get(v)) {
        if (i != u) {
            jump[1] = Math.min(jump[1], jump[0] + Time(i, v));
        }
    }
    return Math.min(jump[0], jump[1]);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
