            if (!graph.containsKey(u)) graph.put(u, new TreeMap<>());
            graph.get(u).put(v, true);
            if (!graph.containsKey(v)) graph.put(v, new TreeMap<>());
            graph.get(v).put(u, true);
        }
        return minTime(graph, hasApple, 0, new HashMap<>());
    }

private int minTime(Map<Integer, Map<Integer, Boolean>> graph, boolean[] hasApple, int root, Map<Integer, Integer> visited) {
        int time = 0;
        for (Map.Entry<Integer, Boolean> entry : graph.getOrDefault(root, new TreeMap<>()).entrySet()) {
            int child = entry.getKey();
            boolean hasChildApple = entry.getValue();
            if (hasChildApple || (visited.containsKey(child) && visited.get(child) == 0)) {
                visited.put(child, 1);
                int childTime = minTime(graph, hasApple, child, visited);
                time += childTime;
                if (childTime > 0 || child == root) time += 2;
            }
        }
        return time;
    }

