    for (int[] edge : edges) {
        graph[edge[0]] |= (1 << edge[1]);
        graph[edge[1]] |= (1 << edge[0]);
    }
    int time = 0;
    if (dfs(0, graph, hasApple, time)) {
        time++; // Count the return time to node 0
    }
    return time;
}

private boolean dfs(int node, int[] graph, boolean[] hasApple, int time) {
    int appleCount = 0;
    for (int child : graph[node]) {
        if ((graph[child] & (1 << node)) != 0 && dfs(child, graph, hasApple, time)) {
            appleCount++; // Count apples if any in subtree
        }
    }
    if (hasApple[node] || appleCount > 0) {
        time += 2; // Time to collect apple and return to root
    }
    return appleCount > 0;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    List<Character> chars = new ArrayList<>();

    // Count occurrences of each character in the string
    for (char c : s.toCharArray()) {
        chars.add(c);
    }

    // Sort characters in ascending and descending order
    Collections.sort(chars, null);
    Collections.sort(chars, Collections.reverseOrder());

    // Reconstruct the string using the sorted order
    for (int i = 0; i < chars.size(); i += 2) {
        result.append(chars.get(i));
    }
    for (int i = 1; i < chars.size(); i += 2) {
        result.append(chars.get(i));
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    List<Character> characters = Arrays.asList();
    // Convert input string into a character array and add each character to the list
    for (char ch : s.toCharArray()) {
        characters.add(ch);
    }

    // Sort the list of characters
    Collections.sort(characters);

    // Start from the smallest character
    while (!characters.isEmpty()) {
        // Select the smallest character and append it to the result
        result.append(characters.remove(0));

        // If the selected character is the largest in the list, remove it; otherwise, replace it with the next smallest
        if (characters.isEmpty() || characters.get(0) != result.charAt(result.length() - 1)) {
            Collections.sort(characters);
        } else {
            characters.remove(0);
        }

        // Select the largest character and append it to the result
        result.append(characters.remove(characters.size() - 1));

        // If the selected character is the smallest in the list, remove it; otherwise, replace it with the next largest
        if (characters.isEmpty() || characters.get(characters.size() - 1) != result.charAt(result.length() - 1)) {
            Collections.sort(characters);
        } else {
            characters.remove(characters.size() - 1);
        }
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder stringBuilder = new StringBuilder();
    int[] frequency = new int[26];

    // Count the frequency of each character
    for (char c : s.toCharArray()) {
        frequency[c - 'a']++;
    }

    int index = 0;
    while (index < s.length()) {
        // Pick the smallest character and append it
        for (int i = 0; i < 26; i++) {
            if (frequency[i] > 0) {
                stringBuilder.append((char) ('a' + i));
                frequency[i]--;
                index++;
                break;
            }
        }
        // Pick the largest character and append it
        for (int i = 25; i >= 0; i--) {
            if (frequency[i] > 0) {
                stringBuilder.append((char) ('a' + i));
                frequency[i]--;
                index++;
                break;
            }
        }
    }

    return stringBuilder.toString();
}

public String sortString(String s) {
    Queue<Character> queue = new PriorityQueue<>();
    for (char c : s.toCharArray()) {
        queue.offer(c);
    }

    StringBuilder result = new StringBuilder();
    char lastAdded = ' ';
    while (!queue.isEmpty()) {
        boolean isAscending = queue.peek() > lastAdded;
        while (!queue.isEmpty() && (isAscending ? queue.peek() < lastAdded : queue.peek() > lastAdded)) {
            result.append(queue.poll());
        }
        lastAdded = queue.poll();
        isAscending = !isAscending;
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder sortedString = new StringBuilder();
    int[] charCount = new int[26];

    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    while (sortedString.length() < s.length()) {
        // Append smallest characters
        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0) {
                sortedString.append((char) ('a' + i));
                charCount[i]--;
            }
        }

        // Append largest characters
        for (int i = 25; i >= 0; i--) {
            if (charCount[i] > 0) {
                sortedString.append((char) ('a' + i));
                charCount[i]--;
            }
        }
    }

    return sortedString.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length <= 1) return false;

    int totalSum = 0;
    for (int num : nums) totalSum += num;

    int targetSum = totalSum / 2;
    int sumLeft = 0;
    int sumRight = 0;

    for (int num : nums) {
        sumLeft += num;
        sumRight = totalSum - sumLeft;
        if (sumLeft == targetSum && sumRight == targetSum) return true;
    }

