public boolean splitArraySameAverage(int[] nums) {
    int sum = Arrays.stream(nums).sum();
    int avg = sum / nums.length;

    Map<Integer, Integer> map = new HashMap<>();
    map.put(0, 1);

    int currSum = 0;
    for (int num : nums) {
        currSum += num;
        if (currSum - avg >= 0 && map.containsKey(currSum - avg)) {
            return true;
        }
        map.put(currSum, map.getOrDefault(currSum, 0) + 1);
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length, total = 0;
    for (int num : nums) total += num;

    if (total % 2 != 0) return false;

    total /= 2;
    Set<Integer> seen = new HashSet<>();
    for (int num : nums) {
        int remaining = total - num;
        if (remaining == 0 || seen.contains(remaining)) return true;
        seen.add(num);
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    int n = nums.length;
    if (n % 2 != 0) {
        return false; // If length is odd, it's impossible to split into two equal averages
    }

    int fixedSum = totalSum / 2;
    int leftSum = 0;

    for (int i = 0; i < n - 1; i++) {
        leftSum += nums[i];
        if (leftSum == fixedSum) {
            return true; // If at any point the left sum equals the fixed sum, it's possible to split
        }
    }

    return false; // If we exhaust all possibilities without finding a valid split, return false
}

public static boolean splitArraySameAverage(int[] nums) {
        if (nums.length <= 1) {
            return false;
        }

        int sum = Arrays.stream(nums).sum();
        double targetSum = sum / 2;

        for (int i = 1; i < nums.length; ++i) {
            if (targetSum * i % nums.length == 0) {
                int otherSum = targetSum * (nums.length - i) / i;

                if (Arrays.stream(nums).filter(num -> num == targetSum).count() == i) {
                    if (Arrays.stream(nums).filter(num -> num != targetSum).count() == nums.length - i) {
                        return true;
                    }
                }

                if (Arrays.stream(nums).filter(num -> num == otherSum).count() == nums.length - i) {
                    if (Arrays.stream(nums).filter(num -> num != otherSum).count() == i) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 1) return cost[0];
    if (cost.length == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length <= 1) {
        return cost.length == 0 ? 0 : cost[0];
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length <= 1) {
        return cost.length == 1 ? cost[0] : 0;
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    // Create an array to store the minimum cost to reach each step
    int[] dp = new int[cost.length + 1];

    // Base cases
    dp[0] = cost[0];
    dp[1] = cost[1];

    // Calculate the minimum cost to reach each step
    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i-1];
    }

    // The minimum cost to reach the top is at the end of the dp array
    return dp[cost.length];
}

