public boolean hasAllCodes(String s, int k) {
    // Check if the string is shorter than k characters
    if (s.length() < k) {
        return false;
    }
    // Create a set to keep track of unique binary strings of length k
    Set<String> uniqueStrings = new HashSet<>();
    // Iterate through the string, window size is k
    for (int i = 0; i <= s.length() - k; i++) {
        String window = s.substring(i, i + k);
        // Add the current window to the set
        uniqueStrings.add(window);
    }
    // If the size of the set is equal to 2^n, all codes are found
    return uniqueStrings.size() == (1 << k);
}

boolean hasAllCodes(String s, int k) {
