public int minInsertions(String s) {
    int balance = 0, insertionNeeded = 0;

    // Iterate through each character in the string
    for (char c : s.toCharArray()) {
        if (c == '(') {
            // Increment balance
            balance++;
        } else {
            // Decrement balance if it's closing paren
            balance--;
            // If balance is negative, it means we need an open paren before this close one
            if (balance < 0) {
                // Increment insertionNeeded by 1
                insertionNeeded++;
                // Increment balance to make it neutral (a pair is formed)
                balance++;
            }
        }
    }

    // Calculate the total number of insertions needed, including the first open paren we added to balance the string
    int totalInsertions = insertionNeeded + balance;

    return totalInsertions;
}

public int minInsertions(String s) {
    int left = 0; // Count of unmatched left brackets
    int right = 0; // Count of unmatched right brackets

    for (char c : s.toCharArray()) {
        if (c == '(') {
            left++;
        } else {
            if (left > 0) {
                left--; // If there's a matching left bracket, balance them
            } else {
                right++; // If not, add one right bracket to balance
            }
        }
    }

    // The total minimum number of bracket insertions required is the sum of unmatched right brackets and left brackets.
    return right + left;
}

public int minInsertions(String s) {
    int n = s.length(), excessLeft = 0, extraRight = 0, insertionNeeded = 0;
    for (int i = 0; i < n; i++) {
        if (s.charAt(i) == '(') {
            excessLeft++;
        } else {
            excessLeft--;
            if (excessLeft < 0) {
                insertionNeeded++;
                excessLeft = 0;
            }
        }
    }
    insertionNeeded += excessLeft; // Always insert missing '('
    return insertionNeeded + extraRight; // Always insert missing ')'
}

