public int minOperations(int n) {
    int res = 0;
    long[] arr = new long[n];
    for(int i = 0; i < n; i++){
        arr[i] = (2 * i) + 1; 
    }

    while(!allZeroes(arr)){
        int diffIdx = diffEle(arr);
        arr[diffIdx] -= 1;
        arr[diffIdx - 1] += 1;
        res++;
    }
    return res;
}

private int diffEle(long[] arr){
    for(int i = 0; i <= arr.length/2; i++){
        if(arr[i] != arr[arr.length - i - 1]){
            return i;
        }
    }
    return arr.length - 1;
}

private boolean allZeroes(long[] arr){
    for(int i = 0; i < arr.length; i++){
        if(arr[i] != 0){
            return false;
        }
    }
    return true;
}

