    fibonacci.add(b);
    while (b < k) {
        int next = a + b;
        fibonacci.add(next);
        a = b;
        b = next;
    }
    int result = 0;
    for (int i = fibonacci.size() - 1; i >= 0; i--) {
        if (k >= fibonacci.get(i)) {
            result++;
            k -= fibonacci.get(i);
        }
    }
    return result;
}

