        fibs.add(fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2));
    }
    int count = 0;
    int i = fibs.size() - 1;
    while (k > 0) {
        if (fibs.get(i) <= k) {
            k -= fibs.get(i);
            count++;
        } else {
            i--;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    int n = 1, prev = 1;
    while (n <= k) {
        fib.add(n);
        int curr = n + prev;
        n = curr;
        prev = n - prev;
    }
    int res = 0, p = fib.size() - 1;
    while (k > 0) {
        if (fib.get(p) <= k) {
            res++;
            k -= fib.get(p);
        } else {
            p--;
        }
    }
    return res;
}

