public String makeGood(String s) {
    int index = 0;
    while (index < s.length() - 1) {
        if (s.charAt(index) > s.charAt(index + 1) && s.charAt(index) - s.charAt(index + 1) == 32 || 
            s.charAt(index) < s.charAt(index + 1) && s.charAt(index) - s.charAt(index + 1) == -32) {
            s = s.substring(0, index) + s.substring(index + 2);
