   return process(s, 0, seen);
}

private int process(String s, int start, Set<String> seen) {
   if (start == s.length()) return seen.size();

   int maxUnique = 0;

   for (int i = start; i < s.length(); i++) {
      String current = s.substring(start, i + 1);
      if (!seen.contains(current)) {
         seen.add(current);
         maxUnique = Math.max(maxUnique, process(s, i + 1, seen));
         seen.remove(current);
      }
   }

   return maxUnique;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n <= 1) return n;

    int maxUnique = 0;
    boolean[] used = new boolean[n];

    // Function to count unique substrings starting from index i
    int countUniqueStartingFrom(int i) {
        if (used[i]) return 0;
        int prefixStart = i;
        int uniqueCount = 1;
        used[i] = true;

        while (prefixStart < n) {
            String prefix = s.substring(prefixStart);
            if (!used[prefixStart]) {
                uniqueCount++;
                used[prefixStart] = true;
            }
            prefixStart++;
        }

        return uniqueCount;
    }

    // Try all possible split points
    for (int i = 0; i < n; i++) {
        maxUnique = Math.max(maxUnique, countUniqueStartingFrom(i));
    }

    return maxUnique;
}

