public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxLength = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        Set<String> seen = new HashSet<>();
        if ((seen.add(prefix) && findNextSubstring(s, i, seen))) {
            maxLength = Math.max(maxLength, i);
        }
    }

    return maxLength;
}

private boolean findNextSubstring(String s, int currentStart, Set<String> seen) {
    if (currentStart >= s.length()) {
        return true;
    }

    for (int i = currentStart + 1; i <= s.length(); i++) {
        String prefix = s.substring(currentStart, i);
        if (!seen.add(prefix) && findNextSubstring(s, i, seen)) {
            return true;
        }
    }

    return false;
}

