public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder(n);
    for (int i = n-1; i >= 0 && k > 0; i--) {
        int charValue = (k - 1) / (n - i) + 1;
        result.insert(0, (char) (charValue + 'a' - 1));
        k -= charValue * (n - i);
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int currentValue = result.length();
        if (k < (currentValue + 26)) {
            result.append((char) ('a' + k));
            k -= currentValue;
        } else {
            char c = (char) ('a' + 26 - 1);
            if (i + 1 < n) {
                result.append(c);
            } else {
                result = new StringBuilder(result.substring(0, i) + c);
            }
            k -= (currentValue + 26 - 1);
        }
    }
    return result.toString();
}

