}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0;
    }

    // We use a loop to calculate the probability
    double current = 1.0;
    for (int i = 2; i <= n; i++) {
        double next = (current * (n - i + 1)) / (n - 2);
        current = next;
    }

    return current;
}

public static double calculateProbability(int n) {
    // Base case: If there is only one passenger, the probability is 1
    if (n == 1) return 1.0;
    // Base case: If there are two pasengers, the probability is 0
    else if (n == 2) return 0.0;
    // Recursive case: The probability is the sum of the probabilities of the two scenarios
    return (double) 1 / 2 * calculateProbability(n - 1) + (double) 1 / 2 * calculateProbability(n - 2);
}

