private static boolean isSteppingNumber(int num) {
    int previousDigit = -1;
    while (num > 0) {
        int currentDigit = num % 10;
        // Check if the current digit is not one more or one less than the previous digit
        if (Math.abs(currentDigit - previousDigit) != 1) return false;
        previousDigit = currentDigit;
        num /= 10;
    }
    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i <= 9; i++) {
        if (i * 10 >= low) {
            backtrack(i, i * 10, high, result);
        }
    }
    result.sort(Integer::compareTo);
    return result;
}

private static void backtrack(int current, int next, int high, List<Integer> result) {
    if (next > high) {
        return;
    }
    result.add(current);
    if (current != 0) {
        backtrack(current - 1, current * 10 + (current - 1), high, result);
    }
    backtrack(current + 1, current * 10 + (current + 1), high, result);
}

