public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length, n = mat[0].length, maxLength = 0;
    if (n < 2) {
        for (int i = 0; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (mat[i][j] == 1 && mat[i][j-1] == 1) {
                    maxLength = Math.max(maxLength, 2);
                }
            }
        }
        return maxLength;
    }

    // Create direction arrays for left, right, up, and down
    int[][] dirs = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

    for (int i = 0; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (mat[i][j] == 1 && (i == 0 || mat[i-1][j] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[0]));
            }
            if (mat[i][j] == 1 && (i == m-1 || mat[i+1][j] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[1]));
            }
            if (mat[i][j] == 1 && (j == 0 || mat[i][j-1] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[2]));
            }
            if (mat[i][j] == 1 && (j == n-1 || mat[i][j+1] == 0)) {
                maxLength = Math.max(maxLength, dfs(mat, i, j, dirs[3]));
            }
        }
    }

    return maxLength;
}

private static int dfs(int[][] mat, int i, int j, int[] dir) {
    int result = 1;
    int x = i, y = j;
    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
        result++;
        x += dir[0];
        y += dir[1];
    }

    x = i;
    y = j;
    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
        result++;
        x -= dir[0];
        y -= dir[1];
    }

    return result;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, increaseLineLength(mat, i, j));
            }
        }
    }

    return maxLength;
}

private static int increaseLineLength(int[][] mat, int i, int j) {
    int horizontalLength = 1;
    while (i < mat.length && mat[i][j] == 1) {
        horizontalLength++;
        i++;
    }

    int verticalLength = 1;
    while (j < mat[0].length && mat[i][j] == 1) {
        verticalLength++;
        j++;
    }

    int diagonalLength = 1;
    int leftDiagonalLength = 1;
    int rightDiagonalLength = 1;
    while (i < mat.length && j < mat[0].length && mat[i][j] == 1) {
        diagonalLength++;
        leftDiagonalLength++;
        rightDiagonalLength++;
        i++;
        j++;
    }

    int antiDiagonalLength = 1;
    int leftAntiDiagonalLength = 1;
    int rightAntiDiagonalLength = 1;
    while (i < mat.length && j >= 0 && mat[i][j] == 1) {
        antiDiagonalLength++;
        leftAntiDiagonalLength++;
        rightAntiDiagonalLength++;
        i++;
        j--;
    }

    return Math.max(Math.max(horizontalLength, verticalLength),
                     Math.max(diagonalLength, rightDiagonalLength),
                     Math.max(antiDiagonalLength, leftAntiDiagonalLength));
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
