    // for each coordinate (i, j), check all 4 directions
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int len = 1;
                // check horizontal direction from (i, j) to the right side
                while (j + len < n && mat[i][j + len] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);

                len = 1;
                // check horizontal direction from (i, j) to the left side
                while (j - len >= 0 && mat[i][j - len] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);

                len = 1;
                // check vertical direction from (i, j) to the bottom side
                while (i + len < m && mat[i + len][j] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);

                len = 1;
                // check vertical direction from (i, j) to the top side
                while (i - len >= 0 && mat[i - len][j] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);

                len = 1;
                // check diagonal direction from (i, j) to the bottom right corner
                while (i + len < m && j + len < n && mat[i + len][j + len] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);

                len = 1;
                // check diagonal direction from (i, j) to the top left corner
                while (i - len >= 0 && j - len >= 0 && mat[i - len][j - len] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);

                len = 1;
                // check anti-diagonal direction from (i, j) to the top right corner
                while (i + len < m && j - len >= 0 && mat[i + len][j - len] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);

                len = 1;
                // check anti-diagonal direction from (i, j) to the bottom left corner
                while (i - len >= 0 && j + len < n && mat[i - len][j + len] == 1) {
                    len++;
                }
                maxLength = Math.max(maxLength, len);
            }
        }
    }
    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;

    int m = mat.length;
    int n = mat[0].length;
    int[][] dp = new int[m][n];

    int maxLength = 0;

    // Initialize dp array
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                // Calculate horizontal, vertical, diagonal, and anti-diagonal lengths
                if (i - 1 >= 0 && mat[i - 1][j] == 1) dp[i][j] += dp[i - 1][j];
                if (j - 1 >= 0 && mat[i][j - 1] == 1) dp[i][j] += dp[i][j - 1];
                if (i - 1 >= 0 && j - 1 >= 0 && mat[i - 1][j - 1] == 1) dp[i][j] += dp[i - 1][j - 1];
                if (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) dp[i][j] += dp[i + 1][j + 1];
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int maxLength = 0;
    int[][] directions = {
        {0, 1}, {1, 0}, {1, 1}, {-1, -1} // Up, Right, Diagonal, Anti-Diagonal
    };

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                for (int[] dir : directions) {
                    int x = i + dir[0], y = j + dir[1];
                    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
                        currentLength++;
                        x += dir[0];
                        y += dir[1];
                    }
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }

    return maxLength;
}

