    int[][] dp = new int[1 << length][length];
    Arrays.fill(dp, -1);

    return squarePermutationsRecursive(A, 0, length - 1, dp);
}

private static int squarePermutationsRecursive(int[] A, int start, int end, int[][] dp) {
    if (start == end) {
        return 1;
    }

    if (dp[start][end] != -1) {
        return dp[start][end];
    }

    int count = 0;
    for (int i = start + 1; i <= end; i++) {
        if (isPerfectSquare(A[start] + A[i])) {
            int result = squarePermutationsRecursive(A, i, end, dp);
            if (result != -1) {
                count += result;
            }
        }
    }

    dp[start][end] = count;
    return count;
}

