public static int squarePermutations(int[] A) {
    if (A.length == 1) {
        return A[0] % 4 == 0 ? 1 : 0;
    }

    ArrayList<int[]> combinations = new ArrayList<>();
    generateCombinations(A, 0, new ArrayList<>(), combinations);

    int count = 0;
    for (int[] permutation : combinations) {
        boolean isSquare = true;
        for (int i = 0; i < permutation.length - 1; i++) {
            if (!isPerfectSquare(permutation[i] + permutation[i + 1])) {
                isSquare = false;
                break;
            }
        }
        if (isSquare) {
            count++;
        }
    }

    return count;
}

private static void generateCombinations(int[] array, int start, ArrayList<Integer> current, ArrayList<int[]> combinations) {
    if (current.size() == array.length) {
        combinations.add(new ArrayList<>(current));
        return;
    }

    for (int i = start; i < array.length; i++) {
        if (!current.isEmpty() && array[i] >= current.get(current.size() - 1)) {
            continue;
        }
        current.add(array[i]);
        generateCombinations(array, i + 1, current, combinations);
        current.remove(current.size() - 1);
    }
}

