    helper(A, 0, new ArrayList<Integer>(), permutations);
    return permutations.size();
}

private static void helper(int[] A, int start, ArrayList<Integer> current, ArrayList<int[]> permutations) {
    if (start == A.length) {
        if (isSquareArray(current)) {
            Collections.sort(current);
            permutations.add(current.stream().mapToInt(Integer::intValue).toArray());
        }
        return;
    }
    for (int i = start; i < A.length; i++) {
        Collections.swap(current, start, i);
        if (!current.contains(A[start])) {
            helper(A, start + 1, current, permutations);
        }
        Collections.swap(current, start, i);
    }
}

