public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int k = 0;
    int i = 0;
    int j = 0;

    while (k < rows * cols) {
        result[k++] = mat[i][j];
        if ((i + j) % 2 == 0) {
            // Move diagonally to the right if sum is even
            j += 1;
            if (j == cols) {
                i += 1;
                j -= 1;
            }
        } else {
            // Move diagonally to the left if sum is odd
            i += 1;
            if (i == rows) {
                j += 1;
                i -= 1;
            }
        }
    }

    return result;
}

