public static int findSmallestInteger(int n) {
    // Convert integers to strings to work with individual digits
    String nStr = String.valueOf(n);
    int[] digits = nStr.chars().map(Character::getNumericValue).toArray();

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Check if sorting gives the same number, which means no smaller number can be formed
    boolean allDigitsEqual = true;
    for (int i = 1; i < digits.length; i++) {
        if (digits[i] != digits[0]) {
            allDigitsEqual = false;
            break;
        }
    }

    // If all digits are the same, it's not possible to form a smaller number
    if (allDigitsEqual) {
        return -1;
    }

    // Find the position to insert the smallest possible digit to the left of the first unequal digit
    int smallIndex = 1;
    for (; smallIndex < digits.length; smallIndex++) {
        if (digits[smallIndex] != digits[0]) {
            break;
        }
    }

    // Extract the part of the number before the first unequal digit
    int smallPart = Integer.parseInt(String.valueOf(digits, 0, smallIndex));

    // Calculate the position to insert the smallest possible digit to the right of the equal digit
    int grandSmallPart = Integer.parseInt(String.valueOf(digits, smallIndex));

    // Calculate the next number by inserting the smallest possible digit at the calculated positions
    int place = 1;
    for (int i = 0; i < smallPart * 10 - grandSmallPart; i++, place *= 10) {
        digit[i] = digits[smallIndex] + 1;
        if (digit[i] == 10) {
            digit[i] = 0;
        } else {
            break;
        }
    }

    // Combine the parts to form the new number and return
    return smallPart * 10 + grandSmallPart + digit[0];
}

public static int findSmallestInteger(int n) {
