    }

    // Convert the integer to a character array for easier manipulation
    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Find the smallest index 'i' such that digits[i] > digits[i+1]
    int i = -1;
    for (int j = 0; j < length - 1; j++) {
        if (digits[j] < digits[j + 1]) {
            i = j;
        }
    }

    // If no such index exists, no smaller integer can be formed
    if (i == -1) {
        return -1;
    }

    // Find the largest digit 'j' that is smaller than digits[i]
    int j = i;
    for (int k = length - 1; k > i; k--) {
        if (digits[k] > digits[i]) {
            j = k;
        }
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after index 'i' in descending order
    Arrays.sort(digits, i + 1, length);

    // Convert the character array back to an integer
    return Integer.parseInt(new String(digits));
}

