public static boolean isBoomerang(int[][] points) {
    int[] a = points[0];
    int[] b = points[1];
    int[] c = points[2];

    // Check if any of the conditions indicates the points are collinear
    if ((a[0] * b[1] + b[0] * c[1] + c[0] * a[1]) == (a[0] * c[1] + b[0] * a[1] + c[0] * b[1]))
        return false;

    // Check if the points do not form a right triangle
    return b[0] * c[1] != a[0] * b[1];
}

