    int dy2 = points[2][1] - points[0][1];

    // Check for collinearity
    if (dx1 * dy2 == dx2 * dy1)
        return false;

    // Check for a boomerang
    return true;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Invalid input array");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if any two points are the same
    if (x1 == x2 || x2 == x3 || y1 == y2 || y2 == y3) {
        return false;
    }

    // Calculate the area using the determinant method
    int area = (x1*(y2-y3) + x2*(y3-y1) + x3*(y1-y2)) / 2;

    // If the area is zero, the points are collinear, so it's not a boomerang
    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3 || points[0] == points[1] || points[1] == points[2] || points[0] == points[2]) {
        return false;
    }
    int[] x1 = points[0];
    int[] x2 = points[1];
    int[] x3 = points[2];
    return (x2[1] - x1[1]) * (x3[0] - x1[0]) != (x3[1] - x1[1]) * (x2[0] - x1[0]);
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The array must contain exactly 3 points.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // A boomerang has an area greater than 0
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int two = 2, three = 3, five = 5;
    int i = 2;
    while (i <= n) {
        int min = Math.min(dp[two] * 2, Math.min(dp[three] * 3, dp[five] * 5));
        dp[i] = min;
        if (min == dp[two] * 2) two++;
        if (min == dp[three] * 3) three++;
        if (min == dp[five] * 5) five++;
        i++;
    }
    return dp[n];
}

