public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }

    Queue<Integer> pq = new PriorityQueue<>(Comparator.naturalOrder());
    pq.offer(1);
    Set<Integer> seen = new HashSet<>();
    seen.add(1);

    int uglyNumber = 0;
    int countUgly = 0;

    while (countUgly < n) {
        uglyNumber = pq.poll();
        countUgly++;

        if (!seen.contains(2 * uglyNumber)) {
            pq.offer(2 * uglyNumber);
            seen.add(2 * uglyNumber);
        }

        if (!seen.contains(3 * uglyNumber)) {
            pq.offer(3 * uglyNumber);
            seen.add(3 * uglyNumber);
        }

        if (!seen.contains(5 * uglyNumber)) {
            pq.offer(5 * uglyNumber);
            seen.add(5 * uglyNumber);
        }
    }

    return uglyNumber;
}

