public List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;

    // Helper function to create the next number in lexicographical order
    private int next(int num) {
        if (num == 9) return 0;
        return num * 10;
    }

    // Use a priority queue to explore numbers in lexicographical order
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    queue.offer(1);

    int current = 1;
    while (!queue.isEmpty() && current <= n) {
        current = queue.poll();
        result.add(current);

        int nextValue = next(current);
        if (nextValue <= n) {
            queue.offer(nextValue);
        }
    }

    return result;
}

private int next(int num) {
        if (num == 9) return 0;
        return num * 10;
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;
    while (result.size() < n) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            int lastDigit = current % 10;
            current = lastDigit;
            while (current < lastDigit && current * 10 <= n) {
                current *= 10;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;

    int start = 1;

    while(start < n) {
        result.add(start);
        int next = start * 10;
        for(int i = 9; i >= 0 && next <= n; i--) {
            if(next <= n)
            result.add(next);
            next += i;
        }
        start = next;
    }

    result.add(n);

    return result;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }

        generateLexicalOrder(result, n);

        return result;
    }

private static void generateLexicalOrder(List<Integer> result, int n) {
        for (int i = 0; i < 10 && i <= n; i++) {
            result.add(i);
            if (result.size() == n) {
                break;
            }
        }

        if (result.size() < n) {
            result.add(0);
        }

        if (result.isEmpty()) {
            return;
        }

        List<Integer> nextLevel = new ArrayList<>();
        for (int num : result) {
            int lastDigit = num % 10;
            if (lastDigit == 9) {
                nextLevel.add(num / 10);
            } else {
                nextLevel.add(num * 10 + lastDigit + 1);
            }
        }

        recursiveGenerateLexicalOrder(result, n, nextLevel);
    }

private static void recursiveGenerateLexicalOrder(List<Integer> result, int n, List<Integer> nextLevel) {
        List<Integer> newList = new ArrayList<>();
        for (int num : nextLevel) {
            if (num <= n) {
                result.add(num);
                if (result.size() == n) {
                    break;
                }
            }
        }

        if (result.size() >= n) {
            return;
        }

        List<Integer> nextLevel2 = new ArrayList<>();
        for (int num : result) {
            int lastDigit = num % 10;
            if (lastDigit == 9) {
                nextLevel2.add(num / 10);
            } else {
                nextLevel2.add(num * 10 + lastDigit + 1);
            }
        }

        recursiveGenerateLexicalOrder(result, n, nextLevel2);
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;
    while (current <= n) {
        result.add(current);
        int temp = current * 10;
        if (temp > n) break;
        current = temp;
    }
    return result;
}

